#!/usr/bin/env python3
"""Scratch helper: index the coordinating session's transcript texts, query by time/regex.
usage:
  tx.py build
  tx.py between T1 T2 [--who a|u|both] [--grep RE] [--cut N] [--tools]
  tx.py grep RE [--who a|u|both] [--cut N] [--after T] [--before T] [--ctx N]
"""
import sys, json, glob, os, re, pickle

B = '/home/user/fortress-transcripts-blinded/projects/-home-user-fortress/'
FILES = (sorted(glob.glob(B + 'fe616d40-a9c6-56d7-9da1-7168a172765d.until-2026-10-08T15-41.jsonl.parts/*.jsonl'))
         + sorted(glob.glob(B + 'fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl.parts/*.jsonl'))
         + ['/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl'])
PK = '/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/walk/tx.pickle'


def texts(content, tools=False):
    out = []
    if isinstance(content, str):
        return [content]
    if isinstance(content, list):
        for b in content:
            if not isinstance(b, dict):
                continue
            t = b.get('type')
            if t == 'text':
                out.append(b.get('text', ''))
            elif tools and t == 'tool_use':
                inp = b.get('input', {})
                out.append('[TOOL_USE %s] %s' % (b.get('name'), json.dumps(inp)[:3000]))
    return out


def build():
    seen = set()
    rows = []
    for f in FILES:
        with open(f, errors='replace') as fh:
            for n, line in enumerate(fh, 1):
                try:
                    d = json.loads(line)
                except Exception:
                    continue
                u = d.get('uuid')
                if u in seen:
                    continue
                seen.add(u)
                ts = d.get('timestamp')
                if not ts:
                    continue
                typ = d.get('type')
                if typ not in ('user', 'assistant'):
                    continue
                msg = d.get('message', {})
                c = msg.get('content')
                tx = texts(c, tools=True)
                if not tx:
                    continue
                rows.append((ts, typ, bool(d.get('isSidechain')), bool(d.get('isMeta')), u, d.get('parentUuid'),
                             '\n'.join(tx), os.path.basename(os.path.dirname(f)) + '/' + os.path.basename(f), n,
                             msg.get('model')))
    rows.sort(key=lambda r: r[0])
    pickle.dump(rows, open(PK, 'wb'))
    print(len(rows), 'rows')


def load():
    return pickle.load(open(PK, 'rb'))


def show(r, cut):
    ts, typ, side, meta, u, p, tx, f, n, model = r
    tx2 = tx if cut is None or len(tx) <= cut else tx[:cut] + ' ...[cut %d of %d]' % (cut, len(tx))
    print('--- %s %s%s%s %s:%d %s\n%s' % (ts, typ, ' SIDE' if side else '', ' META' if meta else '', f, n, model or '', tx2))


if __name__ == '__main__':
    a = sys.argv[1:]
    if a[0] == 'build':
        build()
        sys.exit()
    who = 'both'; cut = 2500; tools = False; grep = None; after = None; before = None; ctx = 0
    pos = []
    i = 0
    while i < len(a):
        if a[i] == '--who': who = a[i+1]; i += 2
        elif a[i] == '--cut': cut = int(a[i+1]); i += 2
        elif a[i] == '--grep': grep = a[i+1]; i += 2
        elif a[i] == '--after': after = a[i+1]; i += 2
        elif a[i] == '--before': before = a[i+1]; i += 2
        elif a[i] == '--ctx': ctx = int(a[i+1]); i += 2
        elif a[i] == '--tools': tools = True; i += 1
        else: pos.append(a[i]); i += 1
    rows = load()
    def okwho(r):
        if not tools and r[6].startswith('[TOOL_USE') and '\n' not in r[6]:
            return False
        if who == 'a': return r[1] == 'assistant'
        if who == 'u': return r[1] == 'user'
        return True
    if a[0] == 'between':
        t1, t2 = pos[1], pos[2]
        for r in rows:
            if t1 <= r[0] <= t2 and okwho(r) and not r[2]:
                if grep and not re.search(grep, r[6], re.I): continue
                show(r, cut)
    elif a[0] == 'grep':
        rx = re.compile(pos[1], re.I)
        idx = [k for k, r in enumerate(rows) if okwho(r) and rx.search(r[6]) and (not after or r[0] >= after) and (not before or r[0] <= before)]
        for k in idx:
            r = rows[k]
            if ctx:
                m = rx.search(r[6]); s = max(0, m.start() - ctx); e = min(len(r[6]), m.end() + ctx)
                print('--- %s %s%s %s:%d\n...%s...' % (r[0], r[1], ' SIDE' if r[2] else '', r[7], r[8], r[6][s:e]))
            else:
                show(r, cut)
        print('(%d matches)' % len(idx))

